<script>
import {data,profile,updateData,notify,download} from '../lib/store.js';
import {ADMISSION_GROUPS,TOOL_ITEMS,QUICK_ACTIONS,QUICK_GROUPS,VA_ITEM,WORKSPACE_PAGES,workspacePage,directoryResults,addressLetter,DIRECTORY_LINKS} from '../lib/workspace-directory.js';
import AcademicPlanning from './AcademicPlanning.svelte';import Icon from '../lib/components/Icon.svelte';
let {route}=$props();let area=$derived(route.split('/')[0]);let view=$derived(route.split('/')[1]??'overview');let page=$derived(workspacePage(route));let query=$state('');let category=$state('All');let savedOnly=$state(false);let addressType=$state('Permanent Address');
let groups=$derived(area==='admissions'?ADMISSION_GROUPS:QUICK_GROUPS);let title=$derived(area==='admissions'?'My Admissions':area==='tools'?'Other Tools':'Quick Links & Helpful Contacts');let allItems=$derived(WORKSPACE_PAGES.filter(p=>p.href.startsWith(`#/${area}/`)));let visible=$derived(directoryResults(allItems,{query,category,savedOnly,saved:$data.workspace.savedLinks}));let letter=$derived(addressLetter($profile,$data.person,addressType));
function saveLink(p){const list=$data.workspace.savedLinks;updateData({...$data,workspace:{...$data.workspace,savedLinks:list.includes(p.href)?list.filter(x=>x!==p.href):[...list,p.href]}});notify(list.includes(p.href)?'Resource removed from saved links.':'Resource saved for this demo student.');}
function admissionReview(){const list=$data.workspace.admissionChecklist;updateData({...$data,workspace:{...$data.workspace,admissionChecklist:{...list,[view]:list[view]!==true}}});notify('Local preparation checklist updated. No admission offer is accepted.');}
</script>
{#snippet resourceCard(p)}<article class="service-card panel workspace-resource-card"><span class="tile-icon"><Icon name={p.icon??'external'} size={23}/></span><span class="eyebrow">{p.category??p.group??'University resource'}</span><h2>{p.label}</h2><p>{p.description}</p><div class="button-row"><a class="button secondary" href={p.href}>Open<Icon name="arrow" size={15}/></a><button class="icon-button" aria-label={`${$data.workspace.savedLinks.includes(p.href)?'Unsave':'Save'} ${p.label}`} aria-pressed={$data.workspace.savedLinks.includes(p.href)} onclick={()=>saveLink(p)}><Icon name="star" size={18}/></button></div></article>{/snippet}
{#snippet directoryGroup(group)}<section class="panel padded"><div class="section-heading"><h2>{group.label}</h2><Icon name={group.icon} size={21}/></div>{#each group.items as p}<a class="academic-directory-link" href={p.href}><span>{p.label}<small class="directory-description">{p.description}</small></span><Icon name="arrow" size={15}/></a>{/each}</section>{/snippet}
<div class="page-heading"><div><p class="eyebrow">{area==='admissions'?'Your next chapter':area==='tools'?'The tools behind your day':'A helpful place to start'}</p><h1>{title}</h1><p>{area==='admissions'?'Admission information, getting started, housing, orientation, and international support.':area==='tools'?'Familiar tools, clear destinations, and a few favorites close at hand.':'Common actions and the university offices that can help.'}</p></div></div>
{#if view==='overview'}<div class="academic-controls directory-controls"><div class="search-box"><Icon name="search"/><input type="search" aria-label={`Search ${title}`} placeholder="Search names, services, or topics…" bind:value={query}/></div><label>Category<select bind:value={category}><option>All</option>{#each area==='tools'?['Academic','Student life','Medical','Law','Employee']:area==='admissions'?ADMISSION_GROUPS.map(g=>g.label):['Quick Links',...QUICK_GROUPS.map(g=>g.label)] as option}<option>{option}</option>{/each}</select></label><button class="button secondary" aria-pressed={savedOnly} onclick={()=>savedOnly=!savedOnly}><Icon name="star" size={16}/>{savedOnly?'Show all resources':'Show saved resources'}</button></div>
{#if area==='tools'||query||category!=='All'||savedOnly}<p class="muted small spaced" aria-live="polite">{visible.length} {visible.length===1?'resource':'resources'} found{savedOnly?' in your saved links':''}</p><div class="workspace-tools-grid spaced">{#each visible as p}{@render resourceCard(p)}{/each}</div>{#if !visible.length}<div class="panel empty-state"><Icon name="search" size={30}/><h2>{savedOnly?'No saved resources match.':'No matching resources.'}</h2><p>Try another term, category, or save a resource first.</p><button class="button secondary spaced" onclick={()=>{query='';category='All';savedOnly=false;}}>Reset filters</button></div>{/if}
{:else}{#if area==='quick-links'}<section class="panel padded"><h2>Quick Links</h2><div class="quick-action-grid">{#each QUICK_ACTIONS as p}<a class="quick-action" href={p.href}><span class="tile-icon"><Icon name={p.icon}/></span><span><strong>{p.label}</strong><small>{p.description}</small></span><Icon name="arrow" size={16}/></a>{/each}</div></section>{/if}<div class="account-directory spaced">{#each groups as group}{@render directoryGroup(group)}{/each}</div>{#if area==='quick-links'}<a class="panel quick-va-link spaced" href={VA_ITEM.href}><Icon name="file"/><div><strong>{VA_ITEM.label}</strong><p class="muted small">{VA_ITEM.description}</p></div><Icon name="arrow" size={16}/></a>{/if}{/if}<p class="fine-print">Resource names follow the reference screenshots. Official service pages provide current access and instructions. Saved resources stay separate for each demo student.</p>
{:else if page}<nav class="academic-breadcrumb" aria-label="Workspace breadcrumb"><a href={`#/${area}`}>{title}</a><Icon name="chevron" size={12}/><span>{page.group??title}</span></nav><section class="panel padded workspace-detail-heading"><span class="tile-icon"><Icon name={page.icon}/></span><div><h2>{page.label}</h2><p class="muted small">{page.description}</p></div><button class="icon-button" aria-label={`${$data.workspace.savedLinks.includes(page.href)?'Unsave':'Save'} ${page.label}`} aria-pressed={$data.workspace.savedLinks.includes(page.href)} onclick={()=>saveLink(page)}><Icon name="star"/></button></section>
{#if area==='admissions'&&view==='what-if'}<div class="spaced"><AcademicPlanning view="what-if"/></div>
{:else if area==='quick-links'&&view==='address-letter'}<section class="panel padded academic-copy spaced"><h2>Sample address letter</h2><p>Preview a plain-text sample using an address saved in My Profile. This sample is not proof of residency or an official university verification.</p><div class="academic-controls spaced"><label>Address type<select bind:value={addressType}><option>Permanent Address</option><option>Mailing Address</option><option>Residence Hall Address</option><option>Ceremonial Diploma Mailing Address</option></select></label></div>{#if letter}<pre class="sample-letter">{letter}</pre><button class="button primary spaced" onclick={()=>download('sample-address-letter.txt',letter)}>Download sample letter<Icon name="download" size={16}/></button>{:else}<div class="notice"><Icon name="info"/><p>No {addressType.toLowerCase()} is saved for this demo student. Add a fictional address in My Profile, then return here.</p></div>{/if}<div class="button-row spaced"><a class="button secondary" href="#/profile/addresses">Manage sample addresses<Icon name="arrow" size={15}/></a><a class="button secondary" href={DIRECTORY_LINKS.verification} target="_blank" rel="noreferrer">Request an official letter<Icon name="external" size={15}/></a></div></section>
{:else}<div class="academic-resource-layout spaced"><section class="panel padded academic-copy"><h2>{page.internal?'Continue in your workspace':'Open the official resource'}</h2><p>{page.description}</p>{#if page.internal}<p>This shortcut opens the existing {page.internal.startsWith('#/profile')?'My Profile':page.internal.startsWith('#/finances')?'My Finances':'academic'} workflow, so your saved information stays in one place.</p><a class="button primary" href={page.internal}>Continue to {page.label}<Icon name="arrow" size={16}/></a>{:else}<a class="button primary" href={page.url} target="_blank" rel="noreferrer">{page.label}<Icon name="external" size={16}/></a><p class="fine-print">Opens the official university or linked provider resource in a new tab. Sign in there if required.</p>{/if}
{#if area==='admissions'&&view.startsWith('confirm-')}<div class="notice spaced"><Icon name="info"/><p>Admission decisions, confirmation forms, and fees belong in the official application portal. This prototype has no offer to accept and submits no confirmation.</p></div><label class="task-check"><input type="checkbox" checked={$data.workspace.admissionChecklist[view]===true} onchange={admissionReview}/><span><strong>I reviewed these preparation instructions</strong><small>A local checklist note only; your actual admission status is unchanged.</small></span></label>{/if}
{#if area==='admissions'&&view==='housing-rates'}<a class="text-link spaced" href={DIRECTORY_LINKS.dining} target="_blank" rel="noreferrer">Official meal plans & dining rates<Icon name="external" size={15}/></a>{/if}
{#if area==='tools'&&view==='campuslink'}<div class="notice spaced"><Icon name="info"/><p>CampusLINK is now called GetInvolvedUC. The familiar menu name is retained here; the official page points to the current platform.</p></div>{/if}
{#if area==='tools'&&['lcms','gradtracker','twen','symplicity','medonestop'].includes(view)}<p class="fine-print">This specialist system may require a relevant program or university account. Use the official page for current links and access support.</p>{/if}
</section><aside class="panel padded academic-copy"><h3>{page.phone||page.email||page.location?'Contact information':'Before you continue'}</h3>{#if page.location}<p>{page.location}</p>{/if}{#if page.phone}<a class="academic-related" href={`tel:${page.phone.replaceAll('-','')}`}><span>{page.phone}</span><Icon name="phone" size={15}/></a>{/if}{#if page.email}<a class="academic-related" href={`mailto:${page.email}`}><span>{page.email}</span><Icon name="mail" size={15}/></a>{/if}{#if !page.phone&&!page.email&&!page.location}<p>{page.internal?'This link opens another part of this prototype.':'Use the linked official page for current details, deadlines, access, and office contacts.'}</p>{/if}<p class="fine-print">Viewing contact details does not send a message or place a call.</p><a class="academic-related" href={`#/${area}`}>Return to {title}<Icon name="arrow" size={15}/></a></aside></div>{/if}
{:else}<section class="panel empty-state"><h2>Resource not found.</h2><a class="button primary" href={`#/${area}`}>Return to {title}</a></section>{/if}
